INSERT INTO search.demo_product_sheet(listing_id,data) VALUES ('91000000-0000-4000-8000-000000000081', $fixture$ {"sourceKind":"USER_PROVIDED_UNVERIFIED","sourceDescription":"사용자 제공 본식 상품·옵션 텍스트 · 업체명·원문 URL·게시일·최신 가격 미확인","categoryNote":"제공 글은 앨범과 JPG 사진 구성이므로 본식스냅으로 분류했습니다. DVD/영상 상품은 아닙니다.","caveats":["금액의 부가세 포함 여부·출장비·유효 기간·적용 날짜/요일/시각·예약 가능 일정은 미확인입니다.","대표·부대표 지정 금액에는 2인 촬영이 포함되어 별도의 작가 추가비를 자동 부과하지 않습니다.","추가 옵션 표제의 “택 1”과 여러 옵션의 동시 적용 가능 여부는 업체 확인이 필요합니다. 이 화면의 복수 선택은 조합을 비교하는 가정입니다.","연장 촬영은 시간당·작가 1인당 가격입니다. 실제 연장할 인원만 선택하세요. 추가 작가의 기본 촬영은 1부 종료까지입니다.","4K 영상·영상 납품·영상 촬영 인원은 자료에 없습니다. 사진 상품에서 추정하지 않습니다."],"travel":{"minimum":null,"maximum":null,"description":"출장비와 적용 지역이 자료에 없습니다. 업체 확인 필요."},"products":[{"id":"album-60","name":"본식 스냅 + 원판 60p","amount":1300000,"previousAmount":null,"taxStatus":"UNKNOWN","operators":1,"facts":[{"label":"기본 촬영 작가","value":"1인"},{"label":"촬영 범위","value":"예식 시작 1시간 30분 전 신부대기실부터 예식 종료까지 · 피로연장 인사 포함"},{"label":"촬영 원본","value":"약 2,000장 이상으로 안내 · 식순·예식 상황에 따라 차이 있음"},{"label":"신랑신부 앨범","value":"60p 스냅원판 앨범 1권"},{"label":"양가 부모님 앨범","value":"60p 스냅원판 앨범 2권"},{"label":"납품 파일","value":"촬영 원본 + 수정본 60장 · JPG"},{"label":"전달 방법","value":"이메일 전송 · 납기 미기재"}]},{"id":"album-80","name":"본식 스냅 + 원판 80p","amount":1500000,"previousAmount":null,"taxStatus":"UNKNOWN","operators":1,"facts":[{"label":"기본 촬영 작가","value":"1인"},{"label":"촬영 범위","value":"예식 시작 1시간 30분 전 신부대기실부터 예식 종료까지 · 피로연장 인사 포함"},{"label":"촬영 원본","value":"약 2,000장 이상으로 안내 · 식순·예식 상황에 따라 차이 있음"},{"label":"신랑신부 앨범","value":"80p 스냅원판 앨범 1권"},{"label":"양가 부모님 앨범","value":"80p 스냅원판 앨범 2권"},{"label":"납품 파일","value":"촬영 원본 + 수정본 80장 · JPG"},{"label":"전달 방법","value":"이메일 전송 · 납기 미기재"}]}],"options":[{"id":"director","name":"대표 지정 · 2인 촬영 포함","amount":1400000,"productIds":["album-60","album-80"],"description":"대표 + 실장 1인","group":"DESIGNATION","operatorsOverride":2,"additionalOperators":0,"unit":"ONCE"},{"id":"vice-director","name":"부대표 지정 · 2인 촬영 포함","amount":1100000,"productIds":["alb